package com.vk.starscriptmusic.data.local.db.dao

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import androidx.room.Transaction
import androidx.room.Update
import com.vk.starscriptmusic.data.local.db.entity.PlaylistEntity
import com.vk.starscriptmusic.data.local.db.entity.PlaylistTrackCrossRef
import com.vk.starscriptmusic.data.local.db.entity.PlaylistWithTracks
import kotlinx.coroutines.flow.Flow

/**
 * Data Access Object for custom and auto-generated playlists.
 */
@Dao
interface PlaylistDao {

    @Transaction
    @Query("SELECT * FROM playlists ORDER BY isAutoGenerated ASC, name COLLATE NOCASE ASC")
    fun getAllPlaylistsWithTracks(): Flow<List<PlaylistWithTracks>>

    @Transaction
    @Query("SELECT * FROM playlists WHERE isAutoGenerated = 0 ORDER BY name COLLATE NOCASE ASC")
    fun getCustomPlaylistsWithTracks(): Flow<List<PlaylistWithTracks>>

    @Transaction
    @Query("SELECT * FROM playlists WHERE isAutoGenerated = 1 ORDER BY name COLLATE NOCASE ASC")
    fun getAutoGeneratedArtistPlaylists(): Flow<List<PlaylistWithTracks>>

    @Transaction
    @Query("SELECT * FROM playlists WHERE id = :playlistId LIMIT 1")
    fun getPlaylistWithTracksById(playlistId: Long): Flow<PlaylistWithTracks?>

    @Query("SELECT * FROM playlists WHERE name = :name LIMIT 1")
    suspend fun getPlaylistByName(name: String): PlaylistEntity?

    @Query("SELECT * FROM playlists WHERE artistFilter = :artist LIMIT 1")
    suspend fun getArtistPlaylist(artist: String): PlaylistEntity?

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertPlaylist(playlist: PlaylistEntity): Long

    @Update
    suspend fun updatePlaylist(playlist: PlaylistEntity)

    @Query("UPDATE playlists SET name = :newName WHERE id = :playlistId")
    suspend fun updatePlaylistName(playlistId: Long, newName: String)

    @Transaction
    suspend fun reorderPlaylistTracks(playlistId: Long, orderedTrackIds: List<Long>) {
        clearTracksFromPlaylist(playlistId)
        val refs = orderedTrackIds.mapIndexed { index, trackId ->
            PlaylistTrackCrossRef(
                playlistId = playlistId,
                trackId = trackId,
                orderIndex = index
            )
        }
        insertCrossRefs(refs)
    }

    @Query("DELETE FROM playlists WHERE id = :playlistId")
    suspend fun deletePlaylist(playlistId: Long)

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertCrossRef(crossRef: PlaylistTrackCrossRef)

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insertCrossRefs(crossRefs: List<PlaylistTrackCrossRef>)

    @Query("DELETE FROM playlist_track_cross_ref WHERE playlistId = :playlistId")
    suspend fun clearTracksFromPlaylist(playlistId: Long)

    @Query("DELETE FROM playlist_track_cross_ref WHERE playlistId = :playlistId AND trackId = :trackId")
    suspend fun removeTrackFromPlaylist(playlistId: Long, trackId: Long)

    @Query("SELECT * FROM playlists WHERE isAutoGenerated = 0")
    suspend fun getAllCustomPlaylistsRaw(): List<PlaylistEntity>

    @Query("SELECT * FROM playlist_track_cross_ref")
    suspend fun getAllCrossRefsRaw(): List<PlaylistTrackCrossRef>

    @Query("DELETE FROM playlists WHERE isAutoGenerated = 1")
    suspend fun clearAutoGeneratedPlaylists()
}
